import 'package:flutter/material.dart';
import '../../../../app/dependency_injection.dart';
import '../../../../core/conversation/conversation_manager.dart';
import '../../../../core/conversation/conversation.dart';
class ChatDrawer extends StatelessWidget { const ChatDrawer({super.key}); @override Widget build(BuildContext context) { final manager = getIt<ConversationManager>(); return Drawer(child: Column(children: [DrawerHeader(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('AI Core OS', style: Theme.of(context).textTheme.titleLarge), const SizedBox(height: 8), const Text('AI Core OS v1.5.0')] )), Expanded(child: ValueListenableBuilder<List<Conversation>>(valueListenable: manager.conversationsNotifier, builder: (context, list, _) { return ListView.builder(itemCount: list.length, itemBuilder: (context, i) { final conv = list[i]; return ListTile(leading: const Icon(Icons.chat_bubble), title: Text(conv.title, maxLines: 1, overflow: TextOverflow.ellipsis), onTap: () async { await manager.select(conv.id); if (context.mounted) Navigator.pop(context); }, trailing: IconButton(icon: Icon(conv.pinned ? Icons.push_pin : Icons.push_pin_outlined, size: 18), onPressed: () => manager.togglePin(conv.id))); }); })), const Divider(), ListTile(leading: const Icon(Icons.settings), title: const Text('الاعدادات'), onTap: () {}), ListTile(leading: const Icon(Icons.memory), title: const Text('احصائيات الذاكرة'), onTap: () {}),])); } }
